export function createClient({ fetchImpl, now = Date.now, ttlMs } = {}) {
	if (typeof fetchImpl !== "function") throw new TypeError("fetchImpl must be a function");
	const ttl = ttlMs === undefined ? 0 : ttlMs;
	if (!Number.isInteger(ttl) || ttl < 0) throw new RangeError("ttlMs must be an integer of 0 or more");

	const cache = new Map(); // key -> { response, stamp }
	const inflight = new Map(); // key -> promise
	const counts = { hits: 0, misses: 0, fetches: 0 };

	function startFetch(key) {
		const promise = (async () => {
			try {
				counts.fetches++;
				const response = await fetchImpl(key);
				const normalized = { status: response.status, body: response.body };
				if (ttl > 0 && normalized.status >= 200 && normalized.status < 300) {
					cache.set(key, { response: deepCopy(normalized), stamp: now() });
				}
				return normalized;
			} finally {
				if (inflight.get(key) === promise) inflight.delete(key);
			}
		})();
		if (!inflight.has(key)) inflight.set(key, promise);
		return promise;
	}

