		if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
		const key = stripFragment(url);
		const fresh = options !== null && typeof options === "object" && options.fresh === true;
		if (!fresh && ttl > 0 && cache.has(key)) {
			const entry = cache.get(key);
			if (now() - entry.stamp < ttl) {
				counts.hits++;
				return deepCopy(entry.response);
			}
			cache.delete(key);
		}
		counts.misses++;
		const promise = fresh || !inflight.has(key) ? startFetch(key) : inflight.get(key);
		const response = await promise;
		return deepCopy(response);
	}

	function clear(url) {
		if (url === undefined) {
			cache.clear();
			return;
		}
		if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
		cache.delete(stripFragment(url));
	}

	function stats() {
		return { hits: counts.hits, misses: counts.misses, fetches: counts.fetches };
	}

	return { get, clear, stats };
