function deepCopy(value) {
	if (value === null || typeof value !== "object") return value;
	try {
		return structuredClone(value);
	} catch {
		// Values that cannot be structured-cloned (e.g. functions) are
		// returned as-is; there is no general way to copy them.
		return value;
	}
}

function stripFragment(url) {
	const hash = url.indexOf("#");
	return hash === -1 ? url : url.slice(0, hash);
}

export function createClient({ fetchImpl, now = Date.now, ttlMs } = {}) {
	if (typeof fetchImpl !== "function") throw new TypeError("fetchImpl must be a function");
	const ttl = ttlMs === undefined ? 0 : ttlMs;
	if (!Number.isInteger(ttl) || ttl < 0) throw new RangeError("ttlMs must be an integer of 0 or more");

	const cache = new Map(); // key (url without fragment) -> { response, stamp }
	const inflight = new Map(); // key -> promise for the fetch in progress
	const counts = { hits: 0, misses: 0, fetches: 0 };

	function startFetch(key) {
		const promise = (async () => {
			try {
				counts.fetches++;
				const response = await fetchImpl(key);
				const normalized = { status: response.status, body: response.body };
				if (ttl > 0 && normalized.status >= 200 && normalized.status < 300) {
					cache.set(key, { response: deepCopy(normalized), stamp: now() });
				}
				return normalized;
			} finally {
				if (inflight.get(key) === promise) inflight.delete(key);
			}
		})();
		if (!inflight.has(key)) inflight.set(key, promise);
		return promise;
	}

	async function get(url, options) {
		if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
		const key = stripFragment(url);
		const fresh = options !== null && typeof options === "object" && options.fresh === true;
		if (!fresh && ttl > 0 && cache.has(key)) {
			const entry = cache.get(key);
			if (now() - entry.stamp < ttl) {
				counts.hits++;
				return deepCopy(entry.response);
			}
			cache.delete(key);
		}
		counts.misses++;
		const promise = fresh || !inflight.has(key) ? startFetch(key) : inflight.get(key);
		const response = await promise;
		return deepCopy(response);
	}

	function clear(url) {
		if (url === undefined) {
			cache.clear();
			return;
		}
		if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
		cache.delete(stripFragment(url));
	}

	function stats() {
		return { hits: counts.hits, misses: counts.misses, fetches: counts.fetches };
	}

	return { get, clear, stats };
}

